17	package org.apache.kafka.streams.state.internals;
18	
19	import org.apache.kafka.common.utils.Bytes;
20	import org.apache.kafka.streams.state.WindowBytesStoreSupplier;
21	import org.apache.kafka.streams.state.WindowStore;
22	
23	import java.time.Duration;
24	import java.util.Objects;
25	
26	import static org.apache.kafka.streams.internals.ApiUtils.prepareMillisCheckFailMsgPrefix;
27	import static org.apache.kafka.streams.internals.ApiUtils.validateMillisecondDuration;
28	
29	public class RocksDbIndexedTimeOrderedWindowBytesStoreSupplier implements WindowBytesStoreSupplier {
30	    public enum WindowStoreTypes {
31	        DEFAULT_WINDOW_STORE,
32	        INDEXED_WINDOW_STORE
33	    }
34	
35	    private final String name;
36	    private final long retentionPeriod;
37	    private final long segmentInterval;
38	    private final long windowSize;
39	    private final boolean retainDuplicates;
40	    private final WindowStoreTypes windowStoreType;
41	
42	    public static RocksDbIndexedTimeOrderedWindowBytesStoreSupplier create(final String name,
43	                                                                           final Duration retentionPeriod,
44	                                                                           final Duration windowSize,
45	                                                                           final boolean retainDuplicates,
46	                                                                           final boolean hasIndex) {
47	        Objects.requireNonNull(name, "name cannot be null");
48	        final String rpMsgPrefix = prepareMillisCheckFailMsgPrefix(retentionPeriod, "retentionPeriod");
49	        final long retentionMs = validateMillisecondDuration(retentionPeriod, rpMsgPrefix);
50	        final String wsMsgPrefix = prepareMillisCheckFailMsgPrefix(windowSize, "windowSize");
51	        final long windowSizeMs = validateMillisecondDuration(windowSize, wsMsgPrefix);
52	
53	        final long defaultSegmentInterval = Math.max(retentionMs / 2, 60_000L);
54	
55	        if (retentionMs < 0L) {
56	            throw new IllegalArgumentException("retentionPeriod cannot be negative");
57	        }
58	        if (windowSizeMs < 0L) {
59	            throw new IllegalArgumentException("windowSize cannot be negative");
60	        }
61	        if (defaultSegmentInterval < 1L) {
62	            throw new IllegalArgumentException("segmentInterval cannot be zero or negative");
63	        }
64	        if (windowSizeMs > retentionMs) {
65	            throw new IllegalArgumentException("The retention period of the window store "
66	                + name + " must be no smaller than its window size. Got size=["
67	                + windowSizeMs + "], retention=[" + retentionMs + "]");
68	        }
69	
70	        return new RocksDbIndexedTimeOrderedWindowBytesStoreSupplier(name, retentionMs,
71	            defaultSegmentInterval, windowSizeMs, retainDuplicates, hasIndex);
72	    }
73	
74	    public RocksDbIndexedTimeOrderedWindowBytesStoreSupplier(final String name,
75	                                           final long retentionPeriod,
76	                                           final long segmentInterval,
77	                                           final long windowSize,
78	                                           final boolean retainDuplicates,
79	                                           final boolean withIndex) {
80	        this(name, retentionPeriod, segmentInterval, windowSize, retainDuplicates,
81	            withIndex
82	                ? WindowStoreTypes.INDEXED_WINDOW_STORE
83	                : WindowStoreTypes.DEFAULT_WINDOW_STORE);
84	    }
85	
86	    public RocksDbIndexedTimeOrderedWindowBytesStoreSupplier(final String name,
87	                                           final long retentionPeriod,
88	                                           final long segmentInterval,
89	                                           final long windowSize,
90	                                           final boolean retainDuplicates,
91	                                           final WindowStoreTypes windowStoreType) {
92	        this.name = name;
93	        this.retentionPeriod = retentionPeriod;
94	        this.segmentInterval = segmentInterval;
95	        this.windowSize = windowSize;
96	        this.retainDuplicates = retainDuplicates;
97	        this.windowStoreType = windowStoreType;
98	    }
99	
100	    @Override
101	    public String name() {
102	        return name;
103	    }
104	
105	    @Override
106	    public WindowStore<Bytes, byte[]> get() {
107	        switch (windowStoreType) {
108	            case DEFAULT_WINDOW_STORE:
109	                return new RocksDBTimeOrderedWindowStore(
110	                    new RocksDBTimeOrderedWindowSegmentedBytesStore(
111	                        name,
112	                        metricsScope(),
113	                        retentionPeriod,
114	                        segmentInterval,
115	                        false),
116	                    retainDuplicates,
117	                    windowSize);
118	            case INDEXED_WINDOW_STORE:
119	                return new RocksDBTimeOrderedWindowStore(
120	                    new RocksDBTimeOrderedWindowSegmentedBytesStore(
121	                        name,
122	                        metricsScope(),
123	                        retentionPeriod,
124	                        segmentInterval,
125	                        true),
126	                    retainDuplicates,
127	                    windowSize);
128	            default:
129	                throw new IllegalArgumentException("invalid window store type: " + windowStoreType);
130	        }
131	    }
132	
133	    @Override
134	    public String metricsScope() {
135	        return "rocksdb-window";
136	    }
137	
138	    @Override
139	    public long segmentIntervalMs() {
140	        return segmentInterval;
141	    }
142	
143	    @Override
144	    public long windowSize() {
145	        return windowSize;
146	    }
147	
148	    @Override
149	    public boolean retainDuplicates() {
150	        return retainDuplicates;
151	    }
152	
153	    @Override
154	    public long retentionPeriod() {
155	        return retentionPeriod;
156	    }
157	
158	    @Override
159	    public String toString() {
160	        return "RocksDbIndexedTimeOrderedWindowBytesStoreSupplier{" +
161	                   "name='" + name + '\'' +
162	                   ", retentionPeriod=" + retentionPeriod +
163	                   ", segmentInterval=" + segmentInterval +
164	                   ", windowSize=" + windowSize +
165	                   ", retainDuplicates=" + retainDuplicates +
166	                   ", windowStoreType=" + windowStoreType +
167	                   '}';
168	    }
169	}
