17	package org.apache.kafka.streams.kstream.internals;
18	
19	import org.apache.kafka.common.serialization.Serde;
20	import org.apache.kafka.streams.processor.StateStore;
21	import org.apache.kafka.streams.processor.internals.StoreFactory;
22	import org.apache.kafka.streams.state.StoreSupplier;
23	
24	import java.util.Map;
25	
26	/**
27	 * {@code MaterializedStoreFactory} is the base class for any {@link StoreFactory} that
28	 * wraps a {@link MaterializedInternal} instance.
29	 */
30	public abstract class MaterializedStoreFactory<K, V, S extends StateStore> extends AbstractConfigurableStoreFactory {
31	    protected final MaterializedInternal<K, V, S> materialized;
32	
33	    public MaterializedStoreFactory(final MaterializedInternal<K, V, S> materialized) {
34	        super(materialized.dslStoreSuppliers().orElse(null));
35	        this.materialized = materialized;
36	    }
37	
38	    @Override
39	    public boolean loggingEnabled() {
40	        return materialized.loggingEnabled();
41	    }
42	
43	    @Override
44	    public String storeName() {
45	        return materialized.storeName();
46	    }
47	
48	    public String queryableStoreName() {
49	        return materialized.queryableStoreName();
50	    }
51	
52	    public Serde<K> keySerde() {
53	        return materialized.keySerde();
54	    }
55	
56	    public Serde<V> valueSerde() {
57	        return materialized.valueSerde();
58	    }
59	
60	    public StoreSupplier<S> storeSupplier() {
61	        return materialized.storeSupplier();
62	    }
63	
64	    @Override
65	    public Map<String, String> logConfig() {
66	        return materialized.logConfig();
67	    }
68	
69	    @Override
70	    public StoreFactory withCachingDisabled() {
71	        materialized.withCachingDisabled();
72	        return this;
73	    }
74	
75	    @Override
76	    public StoreFactory withLoggingDisabled() {
77	        materialized.withLoggingDisabled();
78	        return this;
79	    }
80	
81	    @Override
82	    public boolean isCompatibleWith(final StoreFactory storeFactory) {
83	        return (storeFactory instanceof MaterializedStoreFactory)
84	                && ((MaterializedStoreFactory<?, ?, ?>) storeFactory).materialized.equals(materialized);
85	    }
86	
