27	/**
28	 * RocksDB-backed timestamped window store with support for record headers.
29	 * <p>
30	 * This store extends {@link RocksDBWindowStore} and implements both
31	 * {@link TimestampedBytesStore} (for timestamp support) and {@link HeadersBytesStore}
32	 * (for header support) marker interfaces.
33	 * <p>
34	 * The storage format for values is: [headersSize(varint)][headersBytes][timestamp(8)][value]
35	 * <p>
36	 * This implementation uses segment-level versioning for backward compatibility:
37	 * <ul>
38	 * <li>Old segments continue to use the legacy format without headers</li>
39	 * <li>New segments use the header-embedded format</li>
40	 * <li>Legacy values are served with empty headers on read</li>
41	 * <li>All new writes use the new format</li>
42	 * </ul>
43	 *
44	 * @see RocksDBWindowStore
45	 * @see HeadersBytesStore
46	 * @see TimestampedBytesStore
47	 */
48	class RocksDBTimestampedWindowStoreWithHeaders extends RocksDBWindowStore implements TimestampedBytesStore, HeadersBytesStore {
49	
50	    RocksDBTimestampedWindowStoreWithHeaders(final SegmentedBytesStore bytesStore,
51	                                             final boolean retainDuplicates,
52	                                             final long windowSize) {
53	        super(bytesStore, retainDuplicates, windowSize);
54	    }
55	
56	    @Override
57	    public <R> QueryResult<R> query(final Query<R> query,
58	                                    final PositionBound positionBound,
59	                                    final QueryConfig config) {
60	        final long start = config.isCollectExecutionInfo() ? System.nanoTime() : -1L;
61	        final QueryResult<R> result;
62	        final Position position = getPosition();
63	
64	        synchronized (position) {
65	            result = QueryResult.forUnknownQueryType(query, this);
66	
67	            if (config.isCollectExecutionInfo()) {
68	                result.addExecutionInfo(
69	                    "Handled in " + this.getClass() + " in " + (System.nanoTime() - start) + "ns"
70	                );
71	            }
72	            result.setPosition(position.copy());
73	        }
74	        return result;
75	    }
76	}
