33	/**
34	 * Materializes a key-value store as either a {@link TimestampedKeyValueStoreBuilder} or a
35	 * {@link VersionedKeyValueStoreBuilder} depending on whether the store is versioned or not.
36	 */
37	public class KeyValueStoreMaterializer<K, V> extends MaterializedStoreFactory<K, V, KeyValueStore<Bytes, byte[]>> {
38	    private static final Logger LOG = LoggerFactory.getLogger(KeyValueStoreMaterializer.class);
39	
40	    public KeyValueStoreMaterializer(
41	            final MaterializedInternal<K, V, KeyValueStore<Bytes, byte[]>> materialized
42	    ) {
43	        super(materialized);
44	    }
45	
46	    @Override
47	    public StoreBuilder<?> builder() {
48	        final DslStoreFormat storeFormat = dslStoreFormat() == null ? DslStoreFormat.TIMESTAMPED : DslStoreFormat.HEADERS;
49	        final KeyValueBytesStoreSupplier supplier = materialized.storeSupplier() == null
50	                ? dslStoreSuppliers().keyValueStore(new DslKeyValueParams(materialized.storeName(), storeFormat))
51	                : (KeyValueBytesStoreSupplier) materialized.storeSupplier();
52	
53	        final StoreBuilder<?> builder;
54	        if (supplier instanceof VersionedBytesStoreSupplier) {
55	            builder = Stores.versionedKeyValueStoreBuilder(
56	                    (VersionedBytesStoreSupplier) supplier,
57	                    materialized.keySerde(),
58	                    materialized.valueSerde());
59	        } else {
60	            if (storeFormat == DslStoreFormat.HEADERS) {
61	                builder = Stores.timestampedKeyValueStoreBuilderWithHeaders(
62	                    supplier,
63	                    materialized.keySerde(),
64	                    materialized.valueSerde());
65	            } else {
66	                builder = Stores.timestampedKeyValueStoreBuilder(
67	                    supplier,
68	                    materialized.keySerde(),
69	                    materialized.valueSerde());
70	            }
71	        }
72	
73	        if (materialized.loggingEnabled()) {
74	            builder.withLoggingEnabled(materialized.logConfig());
75	        } else {
76	            builder.withLoggingDisabled();
77	        }
78	
79	        if (materialized.cachingEnabled()) {
80	            if (builder instanceof VersionedKeyValueStoreBuilder) {
81	                LOG.info("Not enabling caching for store '{}' as versioned stores do not support caching.", supplier.name());
82	            } else {
83	                builder.withCachingEnabled();
84	            }
85	        }
86	
87	
88	        return builder;
89	    }
90	
