97	    @Override
98	    public long historyRetention() {
99	        if (!(materialized.storeSupplier() instanceof VersionedBytesStoreSupplier)) {
100	            throw new IllegalStateException(
101	                    "historyRetention is not supported when not a versioned store");
102	        }
103	        return ((VersionedBytesStoreSupplier) materialized.storeSupplier()).historyRetentionMs();
104	    }
