                ", windowSize=" + windowSize +
                ", retainDuplicates=" + retainDuplicates +
                ", emitStrategy=" + emitStrategy +
                ", isSlidingWindow=" + isSlidingWindow +
                ", isTimestamped=" + isTimestamped +
                '}';
    }
